import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int bp;

    static String next() {
        while (buf[bp] <= ' ') bp++;
        int s = bp;
        while (bp < buf.length && buf[bp] > ' ') bp++;
        return new String(buf, s, bp - s);
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = Integer.parseInt(next()), q = Integer.parseInt(next());
        long[] bal = new long[n];
        for (int i = 0; i < n; i++) bal[i] = Long.parseLong(next());
        // Pending cashback as {due time, account index, amount}, earliest first.
        PriorityQueue<long[]> pending = new PriorityQueue<>((a, b) -> Long.compare(a[0], b[0]));
        for (int id = 1; id <= q; id++) {
            String op = next();
            long ts = Long.parseLong(next()), account = Long.parseLong(next()), amount = Long.parseLong(next());
            // Cashback due at or before this second is credited first.
            while (!pending.isEmpty() && pending.peek()[0] <= ts) {
                long[] e = pending.poll();
                bal[(int) e[1]] += e[2];
            }
            if (account < 1 || account > n) { System.out.println("[" + (-id) + "]"); return; }
            int i = (int) account - 1;
            if (op.equals("deposit")) bal[i] += amount;
            else {
                if (bal[i] < amount) { System.out.println("[" + (-id) + "]"); return; }
                bal[i] -= amount;
                pending.add(new long[] {ts + 86400, i, amount * 2 / 100});
            }
        }
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < n; i++) { if (i > 0) sb.append(','); sb.append(bal[i]); }
        System.out.println(sb.append(']'));
    }
}

package main

import (
	"bufio"
	"container/heap"
	"fmt"
	"os"
	"strconv"
)

type cashback struct {
	due    int64
	idx    int
	amount int64
}

// dueHeap orders pending cashback by due time, earliest first.
type dueHeap []cashback

func (h dueHeap) Len() int           { return len(h) }
func (h dueHeap) Less(i, j int) bool { return h[i].due < h[j].due }
func (h dueHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *dueHeap) Push(x any)        { *h = append(*h, x.(cashback)) }
func (h *dueHeap) Pop() any          { old := *h; x := old[len(old)-1]; *h = old[:len(old)-1]; return x }

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() string { sc.Scan(); return sc.Text() }
	num := func() int64 { v, _ := strconv.ParseInt(next(), 10, 64); return v }
	n, q := int(num()), int(num())
	bal := make([]int64, n)
	for i := range bal {
		bal[i] = num()
	}
	pending := &dueHeap{}
	for id := 1; id <= q; id++ {
		op := next()
		ts, account, amount := num(), num(), num()
		// Cashback due at or before this second is credited first.
		for pending.Len() > 0 && (*pending)[0].due <= ts {
			c := heap.Pop(pending).(cashback)
			bal[c.idx] += c.amount
		}
		if account < 1 || account > int64(n) {
			fmt.Printf("[%d]\n", -id)
			return
		}
		i := int(account - 1)
		if op == "deposit" {
			bal[i] += amount
		} else {
			if bal[i] < amount {
				fmt.Printf("[%d]\n", -id)
				return
			}
			bal[i] -= amount
			heap.Push(pending, cashback{ts + 86400, i, amount * 2 / 100})
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteByte('[')
	for i, b := range bal {
		if i > 0 {
			w.WriteByte(',')
		}
		w.WriteString(strconv.FormatInt(b, 10))
	}
	w.WriteString("]\n")
}
